"""Snap span edges to a fixed step for payroll."""

from typing import Iterable

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """Steps must be positive and divide an hour."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad rounding step: {step!r}")

def snap_minutes(value: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (2 * value + step) // (2 * step) * step

def round_span(span: Span, step: int) -> Span:
    """Round both edges of a span."""
    check_step(step)
    return Span(
        snap_minutes(span.start, step),
        snap_minutes(span.end, step),
    )

def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"

def round_labels(spans: Iterable[Span], step: int):
    """One rounded label per span."""
    check_step(step)
    return [
        span_label(round_span(span, step))
        for span in spans
    ]

