# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:00-17:15")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_edges_snap_to_nearest(self):
        spans = [parse_span("08:56-17:08")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(Span(65, 125), 10), Span(70, 130)
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 245)]
        self.assertEqual(len(round_labels(spans, 5)), 2)

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels(spans, step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

if __name__ == "__main__":
    unittest.main()
